    # Ensure the registry is a dictionary.
    if not isinstance(handlers_registry, dict):
        raise TypeError("Protocol handlers registry must be a dictionary")
    # If no specific version requested, return a shallow copy of the registry.
    if protocol_version is None:
        return handlers_registry.copy()
    # Validate the provided protocol_version type.
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be given as a tuple")
    # Return the handler for the requested version if present.
    if protocol_version in handlers_registry:
        return {protocol_version: handlers_registry[protocol_version]}
