def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.

    The D* nodes expect an ISO‑8601 string without microseconds (e.g. "YYYY-MM-DDTHH:MM:SS").
    This function accepts a ``datetime.datetime`` or ``datetime.date`` object and returns
    the string representation.  If a plain string is supplied it is returned unchanged.
    For any other input ``ValueError`` or ``TypeError`` is raised.
    """
    import datetime

    if dt is None:
        raise ValueError("dt cannot be None")

    # Handle datetime objects
    if isinstance(dt, datetime.datetime):
        # Remove microseconds for D* node compatibility
        return dt.replace(microsecond=0).isoformat()

    # Handle date objects (no time component)
    if isinstance(dt, datetime.date):
        return dt.isoformat()

    # Pass through strings unchanged
    if isinstance(dt, str):
        return dt

    raise TypeError(f"Unsupported type for dt: {type(dt).__name__}")

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        tag = tag.strip()
        if not tag:
            return False
        # Tags typically allow only alphanumerics, hyphens, and underscores.
        import re
        pattern = re.compile(r'^[A-Za-z0-9_-]+$')
        return bool(pattern.match(tag))
    except Exception:
        return False

